int apdu_output(RAPDU_CHAINING *ex, RAPDU *sh) {
  if (response_source.view.read) {
    uint32_t remaining = response_source.view.total_len - response_source.view.offset;
    uint16_t to_send = (uint16_t)MIN(remaining, sh->len);

    // The caller writes SW to sh->data + sh->len after we return, which
    // overwrites bytes that the response source may still need (e.g. the
    // tail of the auth_data in the first chunk of an MC streaming response).
    // Restore any bytes saved on the previous call.
    if (response_tail_len != 0 && response_source.view.offset == response_tail_offset) {
      memcpy(sh->data + response_tail_offset, response_tail, response_tail_len);
      response_tail_len = 0;
    }

    int read = response_source.view.read(response_source.view.ctx, response_source.view.offset, sh->data, to_send);
    if (read < 0 || read > to_send || (read == 0 && remaining != 0)) {
      ERR_MSG("source read failed sent=%lu read=%d\n", (unsigned long)response_source.view.offset, read);
      apdu_response_source_clear();
      sh->len = 0;
      sh->sw = SW_UNABLE_TO_PROCESS;
      return -1;
    }

    // Save the two bytes at the end of this chunk so that the SW byte
    // write by the caller does not corrupt response source data.
    if (sh->data == shared_io_buffer && remaining > (uint32_t)read) {
      const uint16_t tail_len = 2;
      memcpy(response_tail, sh->data + read, tail_len);
      response_tail_offset = (uint16_t)read;
      response_tail_len = tail_len;
    }

    sh->len = (uint16_t)read;
    response_source.view.offset += (uint16_t)read;
    remaining = response_source.view.total_len - response_source.view.offset;
    if (remaining != 0) {
      sh->sw = remaining > 0xFF ? 0x61FF : 0x6100 + remaining;
    } else {
      sh->sw = response_source.view.sw;
      apdu_response_source_clear();
    }
    return 0;
  }

  uint16_t to_send = ex->rapdu.len - ex->sent;
  if (to_send > sh->len) to_send = sh->len;
  if (response_tail_len != 0 && ex->sent == response_tail_offset) {
    // Restore the pending prefix before moving an aliased response chunk.
    // The previous SW trailer or incoming GET RESPONSE may have overwritten it.
    memcpy(ex->rapdu.data + response_tail_offset, response_tail, response_tail_len);
    response_tail_len = 0;
  }
  memmove(sh->data, ex->rapdu.data + ex->sent, to_send);
  sh->len = to_send;
  ex->sent += to_send;
  if (ex->sent < ex->rapdu.len) {
    if (ex->rapdu.data == sh->data) {
      response_tail_len = MIN(ex->rapdu.len - ex->sent, sizeof(response_tail));
      memcpy(response_tail, ex->rapdu.data + ex->sent, response_tail_len);
      response_tail_offset = ex->sent;
    }
    if (ex->rapdu.len - ex->sent > 0xFF)
      sh->sw = 0x61FF;
    else
      sh->sw = 0x6100 + (ex->rapdu.len - ex->sent);
  } else {
    sh->sw = ex->rapdu.sw;
    response_tail_reset();
  }
  return 0;
}

int read_file(const char *path, void *buf, lfs_soff_t off, lfs_size_t len) {
  int err = cache_acquire(read_file);
  if (err < 0) return err;
  lfs_file_t f;
  err = lfs_file_opencfg(&lfs, &f, path, LFS_O_RDONLY, &file_config);
  if (err >= 0) {
    err = seek_and_read(&f, off, buf, len);
    err = close_file_result(&f, err);
  }
  cache_release(read_file);
  return err;
}

static int ctap_response_stream_read(void *ctx, uint8_t *out, size_t max_len, size_t *written) {
  CTAP_response_stream_state *state = (CTAP_response_stream_state *)ctx;
  size_t copied = 0;

  while (copied < max_len && state->current_segment < state->segment_count) {
    CTAP_response_stream_segment *segment = &state->storage.segments[state->current_segment];
    if (segment->off == segment->len) {
      ++state->current_segment;
      continue;
    }

    size_t n = MIN(segment->len - segment->off, max_len - copied);
    size_t written_now = n;
    switch (segment->kind) {
    case CTAP_RESPONSE_STREAM_SEG_MEM:
      memcpy(out + copied, segment->buf + segment->off, n);
      break;
    case CTAP_RESPONSE_STREAM_SEG_FILE:
      if (read_file(segment->path, out + copied, segment->file_off + segment->off, n) != (int)n) return -1;
      break;
    case CTAP_RESPONSE_STREAM_SEG_MLDSA:
      if (ctap_mldsa_stream_read_generated(segment->mldsa, out + copied, n, &written_now) < 0) return -1;
      if (written_now == 0) return -1;
      break;
    }
    segment->off += written_now;
    copied += written_now;
  }

  *written = copied;
  return 0;
}

static int u2f_register_stream_read_at(void *ctx, uint32_t offset, uint8_t *buf, uint16_t len) {
  U2F_register_stream_state *state = (U2F_register_stream_state *)ctx;
  const uint8_t *stream_buf = u2f_register_stream_buffer;
  const size_t prefix_len = sizeof(U2F_register_prefix);
  size_t copied = 0;

  if (offset < prefix_len) {
    size_t n = MIN((size_t)len, prefix_len - offset);
    memcpy(buf, stream_buf + offset, n);
    copied += n;
    offset += (uint32_t)n;
  }

  if (copied < len && offset < prefix_len + state->cert_len) {
    size_t cert_off = offset - prefix_len;
    size_t to_read = MIN((size_t)len - copied, (size_t)state->cert_len - cert_off);
    int ret = read_file(CTAP_CERT_FILE, buf + copied, (lfs_soff_t)cert_off, (lfs_size_t)to_read);
    if (ret < 0) return ret;
    copied += (size_t)ret;
    offset += (uint32_t)ret;
    if ((size_t)ret != to_read) return (int)copied;
  }

  if (copied < len) {
    size_t sig_off = offset - prefix_len - state->cert_len;
    if (sig_off < state->sig_len) {
      size_t n = MIN((size_t)len - copied, (size_t)state->sig_len - sig_off);
      memcpy(buf + copied, stream_buf + prefix_len + sig_off, n);
      copied += n;
    }
  }

  return (int)copied;
}

