static void CTAPHID_ReleasePKERequestStorage(void *ctx) {
  UNUSED(ctx);
  if (!channel.use_pke_buffer) return;
  pke_buffer_clear();
  pke_buffer_release(PKE_BUFFER_OWNER_CTAP);
  channel.use_pke_buffer = 0;
}
